head.script:
// 원본 : ULDFIL59410 코스닥 전문평가신청 작성화면 (/ui/lst/lstinvstg/ULDFIL59410.xml)

/*
 * 화면 동작
 * 1. 화면 로딩시 공통코드를 조회하고, 신청번호가 있으면 상세를 조회
 * 2. [법인 관련 정보] 「우편번호」 「업종코드」 클릭시 각각 팝업 호출, 「주관사」 는 +/- 로 줄을 추가·삭제
 * 3. [평가신청 관련 정보] 「평가기관 수」 선택에 따라 제척기관 입력 줄을 조정, 첨부 슬롯 7개 제공
 * 4. [평가기관 배정 관련 정보] 「연장신청 여부」 선택에 따라 연장기일 입력칸을 전환
 * 5. 「저장」 클릭시 입력값 검증 후 첨부파일과 함께 저장하고 목록으로 이동
 * 6. 처리상태에 따라 「저장」 「삭제」 버튼 표시를 전환
 *
 * 구역 구성
 * 1. 법인 관련 정보 - 사업자·법인등록번호, 주소, 연락처, 업종코드, 주관사 반복입력
 * 2. 신청 관련 정보 - 구분 라디오, 일자, 제척기관 반복입력, 비고, 첨부 3종
 * 3. 처리 관련 정보 - 처리일자, 연장신청 여부에 따른 항목 전환, 첨부
 *
 * 담긴 패턴
 * - 업무 검증 : 사업자등록번호($c.str.isBizID) 이메일($c.str.isEmail) 전화($c.str.isPhone)
 * - 코드 팝업 : 우편번호(콜백형) 업종코드(반환형) 두 방식 모두
 * - 첨부 슬롯 핸들러 통합 - 슬롯 7개 이벤트 5종을 핸들러 5개로
 * - generator 반복입력 2종 - 줄 추가·삭제, 중복 선택 방지
 * - 선택값에 따른 입력 항목 전환
 * - 등록·수정·삭제 상태별 버튼 표시
 * - 목록 이동
 *
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "ULDFIL59410";

/**
 * 첨부 슬롯 정의. 구분코드별로 슬롯을 몇 개 두는지 여기 한 곳에만 적는다.
 *
 * 마크업의 슬롯 id 는 "이름_구분코드_순번" 규칙을 따르므로
 * 이 표와 마크업이 어긋나면 그 슬롯은 조회 결과가 표시되지 않는다.
 * 슬롯을 늘릴 때는 마크업을 추가하고 이 표의 개수만 올린다.
 */
scwin.ATTACH_SLOT = [
	{ fileTpCd : "01", count : 1, name : "신청서" },
	{ fileTpCd : "02", count : 3, name : "서약서·부속서류" },
	{ fileTpCd : "13", count : 3, name : "평가 결과서·기타서류" }
];

// 화면 상태값
scwin.aplcNo = "";			// 값이 있으면 수정, 비어 있으면 등록
scwin.delAttachList = [];	// 삭제 표시한 첨부. 저장 시 함께 보낸다.


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 08. 18
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
	try {
		// 초기화 함수
		await scwin.init();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDFIL59410.onpageload" });
	}
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 08. 18
 * @description 초기화. 전달받은 번호로 상세를 조회하고 화면을 모드에 맞춘다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 받는 파라미터 이름
 *  - 달력 검증 대상
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
	// 화면 이동 시 넘어온 값
	const param = $c.data.getParameter();

	scwin.aplcNo = param?.aplcNo ?? "";

	// 달력에 형식 검증을 걸어 둔다. 직접 타이핑한 값도 이 검증을 탄다.
	$c.date.checkCalendarFormat("cal_foundDd", "yyyyMMdd");
	$c.date.checkCalendarFormat("cal_apctDd", "yyyyMMdd");

	// 시작일이 종료일보다 뒤면 달력이 스스로 막아 준다. 세트마다 따로 걸어야 한다.
	$c.date.compareFromToDate(cal_procsStartDd1, cal_procsEndDd1, ["평가시작일 1", "평가예정종료일 1"], "yyyyMMdd");
	$c.date.compareFromToDate(cal_procsStartDd2, cal_procsEndDd2, ["평가시작일 2", "평가예정종료일 2"], "yyyyMMdd");

	// 바이트 카운터는 여기서 한 번만 건다.
	// 이 공통함수가 안에서 oninput·onchange 를 스스로 bind 하고 즉시 한 번 그린다.
	// onkeyup 마다 다시 부르면 키를 칠 때마다 핸들러가 쌓여 입력이 점점 느려진다.
	$c.util.setTextLengthCounter(ipt_remk, txt_remkByte, {
		maxLength : 2000, checkType : "byte", warnClass : "warn"
	});

	// 코드 목록을 먼저 채운다.
	// 반복입력 셀렉트박스가 이 목록을 itemset 으로 받으므로,
	// 줄을 만들기 전에 채워 두지 않으면 항목이 빈 채로 그려진다.
	// 상세 조회와 분리해 두어야 등록 모드로 열어도 항목이 나온다.
	await scwin.selectCodeList();

	if ($c.util.isNotEmpty(scwin.aplcNo)) {
		await scwin.selectDetail();
	} else {
		// 등록이면 반복입력에 빈 줄을 하나씩 깔아 둔다.
		scwin.setRepeatRows();
	}

	// 조회한 값에 맞춰 항목을 열고 닫는다.
	// 기관수를 먼저 반영해야 연장기일2 판정이 맞는다. 순서를 바꾸지 말 것.
	scwin.setValuInstInfo(dma_detail.get("valuInstSpplCnt"));
	scwin.setExtnInput(dma_detail.get("extnApplYn"), true);

	// 상태에 따른 잠금은 맨 마지막에 건다.
	// 위 두 함수가 항목을 다시 열기 때문에, 먼저 잠그면 도로 풀린다.
	scwin.setFormMode();
};

/**
 * @method
 * @name scwin.selectCodeList
 * @author Inswave
 * @date 2026. 08. 18
 * @description 반복입력 셀렉트박스에 채울 코드 목록을 조회한다.
 *
 * 상세 조회와 따로 부른다. 등록 모드에서는 상세를 조회하지 않으므로
 * 상세 응답에만 코드 목록을 실어 두면 등록할 때 항목이 비어 버린다.
 *
 * 실제 공통코드라면 이 함수 대신 $c.data.setCommonCode 를 쓴다.
 * 화면 전용 코드이거나 조건에 따라 달라지는 목록이면 아래처럼 따로 조회한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action, target
 * @param
 * @returns
 * @hidden N
*/
scwin.selectCodeList = async function () {
	const sbmOptions = {
		id : "sbm_selectCodeList",
		method : "get",
		action : "/api/listing/listinvstg/specialized-evaluation/new-write",
		target : "dlt_codeList=body",
		isProcessMsg : false
	};

	// 이 조회는 target 옵션이 응답을 dlt_codeList 에 바로 꽂아 주므로
	// 결과를 따로 받아 처리할 것이 없다.
	// 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
	await $c.sbm.executeDynamic(sbmOptions);
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_zipCode_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 우편번호 찾기 버튼 클릭.
 *
 * 이 팝업은 결과를 반환값이 아니라 콜백으로 돌려주는 형식이다.
 * 파라미터에 callbackFn 으로 함수 이름을 문자열로 넘긴다.
 * 반환값으로 받는 팝업(업종코드)과 방식이 다르니 섞지 않는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 받은 값을 넣을 컴포넌트
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_zipCode_onclick = function (e) {
	try {
		const options = {
			id : "ZipWinPop",
			type : "pageFramePopup",
			popupName : "우편번호검색",
			width : "650px",
			height : "750px",
			resizable : true
		};

		const param = {
			data : {},
			callbackFn : "scwin.setZipCode"
		};

		$c.win.openPopup("/ui/dis/common/popup_roadZipcode.xml", options, param);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.btn_zipCode_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_indCode_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 업종코드 찾기 버튼 클릭.
 *
 * 이 팝업은 고른 값을 반환값으로 돌려주는 형식이다.
 * await 로 받고 결과가 비었는지로 취소를 판단한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - openPopup 의 팝업 경로, 받은 값을 넣을 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_indCode_onclick = async function (e) {
	try {
		const options = {
			id : "ULDFIL52110",
			popupName : "업종 검색",
			width : 1000,
			height : 600,
			frameModal : "top"
		};

		const result = await $c.win.openPopup("/ui/sample/template/ULDFIL52110.xml", options, {});

		// 고르지 않고 닫으면 결과가 없다.
		if ($c.util.isEmpty(result)) return;

		dma_detail.set("indCd", result.isurCd);
		dma_detail.set("indNm", result.comNm);
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDFIL59410.btn_indCode_onclick" });
	}
};

/**
 * @event
 * @name scwin.rd_valuInstCnt_onviewchange
 * @author Inswave
 * @date 2026. 08. 18
 * @description 신청 기관수 변경. 고른 수만큼 일자 세트를 연다.
 *
 * 기관을 2사 신청하면 기관별로 처리 일자가 따로 생긴다.
 * 화면은 세트를 미리 그려 두고 쓰지 않는 세트를 잠그는 방식이다.
 *
 * 라디오(select1 renderType="radiogroup")의 onviewchange 가 넘기는 값은
 * { oldIndex, oldValue, index, value } 라 newValue 가 없다.
 * info.newValue 로 읽으면 undefined 가 들어가 분기가 한쪽으로 쏠린다.
 * 셀렉트박스는 { oldValue, newValue, ... } 라 서로 다르니 getValue() 로 읽는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.rd_valuInstCnt_onviewchange = function (info) {
	try {
		scwin.setValuInstInfo(rd_valuInstSpplCnt.getValue());
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.rd_valuInstCnt_onviewchange" });
	}
};

/**
 * @event
 * @name scwin.rd_extnApplYn_onviewchange
 * @author Inswave
 * @date 2026. 08. 18
 * @description 연장신청 여부 변경. 값에 따라 연장기일을 열고 닫는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.rd_extnApplYn_onviewchange = function (info) {
	try {
		// 사용자가 직접 고른 경우라 안내를 띄운다. 초기화 때는 띄우지 않는다.
		// 라디오는 info 에 newValue 가 없다(위 rd_valuInstCnt_onviewchange 참고).
		scwin.setExtnInput(rd_extnApplYn.getValue(), false);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.rd_extnApplYn_onviewchange" });
	}
};

/**
 * @event
 * @name scwin.btn_addLeadCom_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 주관사 줄 추가
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_addLeadCom_onclick = function (e) {
	try {
		scwin.addRepeatRow(gen_leadCom);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.btn_addLeadCom_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_delLeadCom_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 주관사 줄 삭제. 마지막 줄은 남긴다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_delLeadCom_onclick = function (e) {
	try {
		scwin.removeRepeatRow(gen_leadCom);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.btn_delLeadCom_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_addExcInst_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 제척기관 줄 추가
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_addExcInst_onclick = function (e) {
	try {
		scwin.addRepeatRow(gen_excInst);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.btn_addExcInst_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_delExcInst_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 제척기관 줄 삭제. 마지막 줄은 남긴다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_delExcInst_onclick = function (e) {
	try {
		scwin.removeRepeatRow(gen_excInst);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.btn_delExcInst_onclick" });
	}
};

/**
 * @event
 * @name scwin.sel_repeat_onviewchange
 * @author Inswave
 * @date 2026. 08. 18
 * @description 반복입력 셀렉트박스 선택 변경. 같은 값을 두 줄에 고르지 못하게 막는다.
 *
 * generator 안의 컴포넌트는 줄마다 복제되므로 논리 id 가 같다.
 * 어느 줄에서 발생했는지는 this 가 속한 목록에서 값을 훑어 판단한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 대상 DataList 와 컬럼 이름
 * @param
 * @returns
 * @hidden N
*/
scwin.sel_repeat_onviewchange = function (info) {
	try {
		// generator 안의 컴포넌트는 줄마다 복제되므로 논리 id 가 같다.
		// 어느 반복입력에서 발생했는지는 논리 id 로 가른다.
		const componentId = this.getOriginalID();
		const isLeadCom = componentId.indexOf("LeadCom") > -1;
		const generator = isLeadCom ? gen_leadCom : gen_excInst;

		if (!scwin.hasDuplicated(generator, componentId, info.newValue)) return;

		$c.win.alert("이미 선택한 항목입니다.");
		this.setValue(info.oldValue ?? "");
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.sel_repeat_onviewchange" });
	}
};

/**
 * @event
 * @name scwin.btn_attach_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 첨부 슬롯의 파일선택 버튼 클릭. 슬롯이 몇 개든 이 함수 하나가 받는다.
 *
 * 원본은 슬롯마다 핸들러를 따로 두어 같은 코드가 7벌이었다.
 * 버튼 id 에서 구분코드와 순번을 읽어 대상 슬롯을 정하면 한 벌로 끝난다.
 *
 * 논리 id 는 getOriginalID() 로 읽는다. getID() 는 스코프 접두사가 붙은 런타임 id 라
 * "btn_attach_01_1" 같은 원래 이름이 나오지 않는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_attach_onclick = function (e) {
	try {
		const key = scwin.getAttachKey(this);

		if (key === null) return;

		const component = scwin.getAttachComponent(key);

		// 한 슬롯에는 파일 하나만 둔다. 이미 있으면 지우고 다시 고르게 한다.
		if (component !== null && $c.util.isNotEmpty(component.getValue())) {
			$c.win.alert("파일을 삭제한 뒤에 다시 선택해 주세요.");
			return;
		}

		// UDC 가 파일 대화상자를 열고, 고른 파일을 안에 보관한 뒤
		// dma_detail 의 file_<구분코드>_<순번> 키에 파일명을 넣는다.
		// 입력칸이 ref 로 묶여 있어 파일명은 저절로 화면에 나타난다.
		mud.attachFileToMap(scwin.getAttachFieldKey(key), dma_detail);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.btn_attach_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_delAttach_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 첨부 슬롯의 삭제 버튼 클릭. 슬롯을 비우고 삭제 대상으로 표시한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_delAttach_onclick = function (e) {
	try {
		const key = scwin.getAttachKey(this);

		if (key === null) return;

		scwin.removeAttachFile(key);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.btn_delAttach_onclick" });
	}
};

/**
 * @event
 * @name scwin.ipt_attach_ondblclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 첨부 파일명 더블클릭. 이미 저장된 파일이면 내려받는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.ipt_attach_ondblclick = function (e) {
	try {
		const key = scwin.getAttachKey(this);

		if (key === null) return;

		scwin.downloadAttachFile(key);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDFIL59410.ipt_attach_ondblclick" });
	}
};

/**
 * @event
 * @name scwin.btn_list_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 목록 버튼 클릭. 저장하지 않고 목록으로 돌아간다.
 *
 * 작성화면에는 반드시 있어야 하는 버튼이다.
 * 저장하지 않은 내용이 있으면 확인을 받는 편이 좋다.
