 * @hidden N
*/
scwin.btn_list_onclick = async function (e) {
	try {
		// 고친 내용이 있는지 공통함수로 확인한다. 화면에서 값을 하나씩 비교하지 않는다.
		// 인자는 DataCollection 객체나 그 배열이다. 아이디 문자열을 넘기면 항상 false 가 된다.
		if ($c.data.isModified([dma_detail])) {
			if (!await $c.win.confirm("저장하지 않은 내용이 있습니다. 목록으로 이동하시겠습니까?")) return;
