///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.selectDetail
 * @author Inswave
 * @date 2026. 08. 18
 * @description 상세·첨부목록·반복입력 값을 조회한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action, 요청 파라미터
 * @param
 * @returns
 * @hidden N
*/
scwin.selectDetail = async function () {
	dma_detail.set("aplcNo", scwin.aplcNo);

	const sbmOptions = {
		id : "sbm_selectDetail",
		method : "get",
		action : "/api/listing/listinvstg/specialized-evaluation/select-one",
		ref : "dma_detail",
		isProcessMsg : false
	};

	// 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
	// 여기서 잡지 않으므로 오류가 나면 아래 처리는 실행되지 않는다.
	const result = await $c.sbm.executeDynamic(sbmOptions);

	// 조회 결과 처리는 submitDoneHandler 옵션 대신 여기서 직접 부른다.
	// 옵션으로 넘기면 await 가 풀린 뒤에 돌아 이어지는 코드와 순서가 어긋난다.
	scwin.sbm_selectDetail_submitdone(result);
};

/**
 * @method
 * @name scwin.sbm_selectDetail_submitdone
 * @author Inswave
 * @date 2026. 08. 18
 * @description 상세 조회 완료. 응답 한 번으로 여러 DataCollection 을 채운다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 응답 구조
 * @param
 * @returns
 * @hidden N
*/
scwin.sbm_selectDetail_submitdone = function (e) {
	const body = e.responseJSON?.body ?? {};

	dma_detail.setJSON(body.detail ?? {});
	dlt_attach.setJSON(body.attachList ?? []);

	// 조회한 값만큼 반복입력 줄을 만들고 값을 넣는다.
	scwin.setRepeatRows(body.leadComList, body.excInstList);

	// 조회된 첨부를 슬롯에 표시한다.
	scwin.setAttachFileName();
};

/**
 * @method
 * @name scwin.deleteDetail
 * @author Inswave
 * @date 2026. 08. 18
 * @description 삭제한다. 되돌릴 수 없으므로 결과를 문장으로 알리고 확인을 받는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로, 확인 문구
 * @param
 * @returns
 * @hidden N
*/
scwin.deleteDetail = async function () {
	if (!await $c.win.confirm("삭제하면 되돌릴 수 없습니다. 삭제하시겠습니까?")) return;

	const sbmOptions = {
		id : "sbm_delete",
		method : "post",
		action : "/api/listing/listinvstg/specialized-evaluation/remove",
		ref : "dma_detail",
		isProcessMsg : false
	};

	const result = await $c.sbm.executeDynamic(sbmOptions);

	// 통신 오류는 공통 오류 핸들러가 안내하므로 화면은 중단만 한다.
	if ($c.util.isEmpty(result.responseJSON)) return;

	await $c.win.alert($c.data.getMessage("com_complete_0150", "삭제"));

	$c.win.moveUrl("/ui/sample/template/ULDFIL59400.xml", {});
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.setFormMode
 * @author Inswave
 * @date 2026. 08. 18
 * @description 등록·수정 모드와 처리상태에 맞춰 버튼과 항목을 맞춘다.
 *
 * 모드 판정은 한 곳에서만 하고 나머지는 이 함수를 부른다.
 * 여러 곳에서 각자 판정하면 조건이 하나 어긋났을 때 찾기 어렵다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 상태별로 보일 버튼과 잠글 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.setFormMode = function () {
	const isModify = $c.util.isNotEmpty(scwin.aplcNo);
	const procsStatCd = dma_detail.get("procsStatCd");

	// 처리상태코드 10 작성중 · 20 제출완료 · 90 완료
	// 작성중인 건만 사용자가 고칠 수 있다. 제출한 뒤에는 담당자가 처리한다.
	const isWriting = $c.util.isEmpty(procsStatCd) || procsStatCd === "10";
	const isSubmitted = procsStatCd === "20";
	const isDone = procsStatCd === "90";

	// 등록인지 수정인지는 별도 제목을 두지 않고 보이는 버튼으로 알린다. 원본도 같은 방식이다.
	// 삭제는 작성중인 기존 건에서만 가능하다. 제출했거나 완료된 건은 지우지 못한다.
	if (isModify && isWriting) { btn_delete.show(""); } else { btn_delete.hide(); }

	// 완료된 건은 저장도 막는다.
	if (isDone) { btn_save.hide(); } else { btn_save.show(""); }

	// 배정 구역은 접수된 뒤 담당자가 채우는 칸이다.
	// 감추지 않고 잠근다. 감추면 화면 구성이 상태에 따라 달라져
	// 이 화면이 몇 구역짜리인지 알 수 없고, 볼 방법도 없어진다.
	scwin.setProcessDisabled(isWriting);

	// 제출한 뒤에는 신청 내용의 첨부를 손대지 못하게 한다. 배정 구역 첨부는 담당자가 쓴다.
	scwin.setApplyAttachDisabled(isSubmitted || isDone);

	// 지금 어느 단계인지 화면에 보여 준다. 버튼이 없는 이유를 사용자가 알 수 있어야 한다.
	txt_statNm.setValue(scwin.getStatusName(procsStatCd));
};

/**
 * @method
 * @name scwin.setProcessDisabled
 * @author Inswave
 * @date 2026. 08. 18
 * @description 배정 구역을 잠그거나 푼다.
 *
 * 아직 접수 전이면 담당자가 채울 칸이라 사용자가 손대지 못하게 한다.
 * 감추는 대신 잠그는 이유는 두 가지다.
 *  - 화면이 몇 구역짜리인지 늘 같아야 사용자가 헷갈리지 않는다.
 *  - 감추면 상태에 따라 아예 볼 수 없는 구역이 생긴다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 잠글 컴포넌트 목록
 * @param
 * @returns
 * @hidden N
*/
scwin.setProcessDisabled = function (isDisabled) {
	// 배정 구역의 입력 컴포넌트를 하나씩 잠근다.
	[cal_procsStartDd1, cal_procsStartDd2, cal_procsEndDd1, cal_procsEndDd2,
		cal_extnDd1, cal_extnDd2, rd_extnApplYn].forEach(component => {
		component.setDisabled(isDisabled);
	});

	// 배정 구역 첨부 버튼도 함께 잠근다.
	scwin.forEachAttachSlot((component, key) => {
		if (key.fileTpCd !== "13") return;

		const attachBtn = $p.getComponentById("btn_attach_" + key.fileTpCd + "_" + key.fileSeq);
		const deleteBtn = $p.getComponentById("btn_delAttach_" + key.fileTpCd + "_" + key.fileSeq);

		if (attachBtn !== null) attachBtn.setDisabled(isDisabled);
		if (deleteBtn !== null) deleteBtn.setDisabled(isDisabled);
	});

	// 왜 못 쓰는지 알려 준다. 잠겨 있기만 하면 고장으로 오해한다.
	if (isDisabled) {
		txt_processGuide.show("");
	} else {
		txt_processGuide.hide();
	}
};

/**
 * @method
 * @name scwin.getStatusName
 * @author Inswave
 * @date 2026. 08. 18
 * @description 처리상태코드를 사람이 읽는 이름으로 바꾼다.
 *
 * 실제 화면에서는 공통코드를 조회해 쓰는 편이 낫다.
 * 코드가 몇 개뿐이고 화면에서만 쓰는 값이면 이렇게 두어도 된다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 상태코드와 이름
 * @param
 * @returns
 * @hidden N
*/
scwin.getStatusName = function (procsStatCd) {
	// 처리상태코드 20 제출완료 · 90 완료. 그 밖은 작성중으로 본다.
	if (procsStatCd === "20") return "제출완료";
	if (procsStatCd === "90") return "완료";

	return "작성중";
};

/**
 * @method
 * @name scwin.setApplyAttachDisabled
 * @author Inswave
 * @date 2026. 08. 18
 * @description 신청 구역 첨부 버튼을 잠그거나 푼다. 배정 구역 첨부는 건드리지 않는다.
 *
 * 슬롯을 하나씩 적지 않고 ATTACH_SLOT 을 훑는다.
 * 구분코드로 걸러내므로 슬롯이 늘어도 이 함수는 고치지 않는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 제외할 구분코드
 * @param
 * @returns
 * @hidden N
*/
scwin.setApplyAttachDisabled = function (isDisabled) {
	scwin.forEachAttachSlot((component, key) => {
		// 배정 구역 첨부는 담당자가 쓰는 것이라 그대로 둔다.
		if (key.fileTpCd === "13") return;

		const attachBtn = $p.getComponentById("btn_attach_" + key.fileTpCd + "_" + key.fileSeq);
		const deleteBtn = $p.getComponentById("btn_delAttach_" + key.fileTpCd + "_" + key.fileSeq);

		if (attachBtn !== null) attachBtn.setDisabled(isDisabled);
		if (deleteBtn !== null) deleteBtn.setDisabled(isDisabled);
	});
};

/**
 * @method
 * @name scwin.setValuInstInfo
 * @author Inswave
 * @date 2026. 08. 18
 * @description 신청 기관수에 맞춰 2번 세트를 열고 닫는다.
 *
 * 세트를 감추지 않고 잠근다(setDisabled). 감추면 화면이 흔들리고
 * 몇 개짜리 화면인지 사용자가 알 수 없다. 잠그면 있다는 것은 보이되 못 쓴다.
 *
 * 잠글 때 값도 함께 비운다. 남겨 두면 보이지 않는 값이 그대로 저장된다.
 *
 * 연장기일2는 두 조건을 모두 만족해야 열린다.
 * 기관수가 2사이고, 연장신청이 「예」일 때다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 세트 개수와 대상 컴포넌트
 * @param
 * @returns
 * @hidden N
*/
scwin.setValuInstInfo = function (valuInstCnt) {
	const isTwo = valuInstCnt === "2";

	scwin.setDateEnabled(cal_procsStartDd2, "procsStartDd2", isTwo);
	scwin.setDateEnabled(cal_procsEndDd2, "procsEndDd2", isTwo);

	// 연장기일2는 연장신청까지 「예」여야 열린다.
	scwin.setDateEnabled(cal_extnDd2, "extnDd2", isTwo && dma_detail.get("extnApplYn") === "Y");
};

/**
 * @method
 * @name scwin.setExtnInput
 * @author Inswave
 * @date 2026. 08. 18
 * @description 연장신청 여부에 따라 연장기일을 열고 닫는다.
 *
 * 연장기일1은 연장신청만 보면 되고, 연장기일2는 기관수까지 함께 본다.
 *
 * isInit 이 true 면 안내를 띄우지 않는다.
 * 화면을 열 때마다 안내가 뜨면 사용자가 읽지 않게 된다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 안내 문구
 * @param
 * @returns
 * @hidden N
*/
scwin.setExtnInput = function (extnApplYn, isInit) {
	const isExtn = extnApplYn === "Y";

	scwin.setDateEnabled(cal_extnDd1, "extnDd1", isExtn);
	scwin.setDateEnabled(cal_extnDd2, "extnDd2", isExtn && dma_detail.get("valuInstSpplCnt") === "2");

	// 연장을 고르면 무엇을 더 해야 하는지 그 자리에서 알려 준다.
	if (isExtn && isInit !== true) {
		$c.win.alert("연장신청 시 연장기일을 입력하고 기타서류(연장 공문)를 첨부하세요.");
	}
};

/**
 * @method
 * @name scwin.setDateEnabled
 * @author Inswave
 * @date 2026. 08. 18
 * @description 달력을 잠그거나 푼다. 잠글 때는 값도 비운다.
 *
 * 잠그면서 값을 비우지 않으면 사용자가 되돌린 뒤에도 이전 값이 남아 저장된다.
 * 잠금과 값 비움을 한 곳에 묶어 두면 빠뜨릴 수 없다.
 * @param
 * @returns
 * @hidden N
*/
scwin.setDateEnabled = function (component, keyId, isEnabled) {
	component.setDisabled(!isEnabled);

	if (!isEnabled) dma_detail.set(keyId, "");
};

/**
 * @method
 * @name scwin.setZipCode
 * @author Inswave
 * @date 2026. 08. 18
 * @description 우편번호 팝업 콜백. 고른 주소를 화면에 넣는다.
 *
 * 팝업이 이 함수를 이름으로 찾아 부르므로 이름을 바꾸면 호출부의 callbackFn 도 함께 바꾼다.
 * @param
 * @returns
 * @hidden N
*/
scwin.setZipCode = function (result) {
	if ($c.util.isEmpty(result)) return;

	dma_detail.set("zipCd", result.zipNo);
	dma_detail.set("addr", result.addr);

	// 상세주소는 사용자가 직접 넣는다. 이전 값이 남지 않게 비운다.
	dma_detail.set("dtlAddr", "");

	ipt_dtlAddr.focus();
};

/**
 * @method
 * @name scwin.setRepeatRows
 * @author Inswave
 * @date 2026. 08. 18
 * @description 반복입력이 비어 있으면 빈 줄을 깔아 준다.
 *
 * 줄이 하나도 없으면 사용자가 「추가」를 눌러야 입력을 시작할 수 있다.
 * @param
 * @returns
 * @hidden N
*/
scwin.setRepeatRows = function (leadComList, excInstList) {
	scwin.fillRepeat(gen_leadCom, "sel_leadCom", leadComList ?? [], "leadComCd");
	scwin.fillRepeat(gen_excInst, "sel_excInst", excInstList ?? [], "excInstCd");
};

/**
 * @method
 * @name scwin.fillRepeat
 * @author Inswave
 * @date 2026. 08. 18
 * @description 조회한 값만큼 줄을 만들고 각 줄에 값을 넣는다.
 *
 * generator 는 DataList 를 묶는 컴포넌트가 아니다.
 * 줄 수는 insertChild 로 직접 늘리고, 각 줄의 컴포넌트는 getChild 로 꺼낸다.
 *
 * 값이 없어도 최소 줄 수만큼은 만들어 둔다.
 * 줄이 하나도 없으면 사용자가 「추가」를 눌러야 입력을 시작할 수 있다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 줄 안의 컴포넌트 id
 * @param
 * @returns
 * @hidden N
*/
scwin.fillRepeat = function (generator, componentId, rows, columnId) {
	const rowCount = Math.max(rows.length, 1);

	// 이미 있는 줄 수와 맞춘다. 부족하면 늘리고 남으면 줄인다.
	while (generator.getLength() < rowCount) generator.insertChild();
	while (generator.getLength() > rowCount) generator.removeChild();

	for (let i = 0; i < rowCount; i++) {
		const component = generator.getChild(i, componentId);

		if (component === null) continue;

		component.setValue(rows[i]?.[columnId] ?? "");
	}
};

/**
 * @method
 * @name scwin.getRepeatValues
 * @author Inswave
 * @date 2026. 08. 18
 * @description 반복입력의 각 줄에서 값을 모아 배열로 돌려준다.
 *
 * 저장할 때 이 배열을 전문에 싣는다.
 * 비어 있는 줄은 뺀다. 사용자가 추가만 하고 고르지 않았을 수 있다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 줄 안의 컴포넌트 id, 돌려줄 항목 이름
 * @param
 * @returns
 * @hidden N
*/
scwin.getRepeatValues = function (generator, componentId, columnId) {
	const values = [];
	const rowCount = generator.getLength();

	for (let i = 0; i < rowCount; i++) {
		const component = generator.getChild(i, componentId);

		if (component === null) continue;

		const value = component.getValue();

		if ($c.util.isEmpty(value)) continue;

		values.push({ [columnId] : value });
	}

	return values;
};

/**
 * @method
 * @name scwin.addRepeatRow
 * @author Inswave
 * @date 2026. 08. 18
 * @description 반복입력에 빈 줄을 하나 추가한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.addRepeatRow = function (generator) {
	generator.insertChild();
};

/**
 * @method
 * @name scwin.removeRepeatRow
 * @author Inswave
 * @date 2026. 08. 18
 * @description 반복입력의 마지막 줄을 지운다. 최소 줄 수는 남긴다.
 *
 * 줄을 전부 지울 수 있게 두면 화면이 비어 무엇을 해야 할지 알 수 없다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 남겨 둘 최소 줄 수
 * @param
 * @returns
 * @hidden N
*/
scwin.removeRepeatRow = function (generator) {
	// 최소 1줄은 남긴다. 더 남겨야 하면 이 숫자와 안내 문구를 함께 고친다.
	if (generator.getLength() <= 1) {
		$c.win.alert("최소 1줄은 작성하셔야 합니다.");
		return;
	}

	// 인자를 주지 않으면 마지막 줄을 지운다.
	generator.removeChild();
};

/**
 * @method
 * @name scwin.hasDuplicated
 * @author Inswave
 * @date 2026. 08. 18
 * @description 목록에 같은 값이 이미 있는지 본다.
 *
 * 빈 값은 중복으로 보지 않는다. 아직 고르지 않은 줄이 여럿일 수 있다.
 * @param
 * @returns
 * @hidden N
*/
scwin.hasDuplicated = function (generator, componentId, value) {
	if ($c.util.isEmpty(value)) return false;

	let count = 0;
	const rowCount = generator.getLength();

	for (let i = 0; i < rowCount; i++) {
		const component = generator.getChild(i, componentId);

		if (component === null) continue;

		if (component.getValue() === value) count++;
	}

	// 방금 고른 줄까지 세므로 2건 이상이면 중복이다.
	return count > 1;
};

/**
 * @method
 * @name scwin.getAttachKey
 * @author Inswave
 * @date 2026. 08. 18
 * @description 첨부 슬롯 컴포넌트에서 구분코드와 순번을 읽는다.
 *
 * 슬롯 컴포넌트 id 를 "이름_구분코드_순번" 으로 지어 두는 것이 이 방식의 전제다.
 * 예) btn_attach_01_1 / ipt_attach_02_3 / btn_delAttach_13_1
 *
 * 논리 id 는 getOriginalID() 로 읽는다.
 * getID() 는 스코프 접두사가 붙은 런타임 id 라 원래 이름이 나오지 않는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - id 규칙을 바꾸면 이 정규식도 함께 바꾼다
 * @param
 * @returns
 * @hidden N
*/
scwin.getAttachKey = function (component) {
	const componentId = component.getOriginalID();
	const matched = componentId.match(/(\d{2})_(\d+)$/);

	if (matched === null) return null;

	return { fileTpCd : matched[1], fileSeq : matched[2] };
};

/**
 * @method
 * @name scwin.getAttachComponent
 * @author Inswave
 * @date 2026. 08. 18
 * @description 구분코드·순번으로 슬롯의 입력칸을 찾는다.
 *
 * $p.getComponentById 는 논리 id 로 찾는다. 화면에 없는 id 면 null 이 온다.
 * @param
 * @returns
 * @hidden N
*/
scwin.getAttachComponent = function (key) {
	return $p.getComponentById("ipt_attach_" + key.fileTpCd + "_" + key.fileSeq);
};

/**
 * @method
 * @name scwin.getAttachFieldKey
 * @author Inswave
 * @date 2026. 08. 19
 * @description 슬롯의 dataMap 키 이름을 만든다.
 *
 * UDC 는 이 이름으로 파일을 보관하고, 저장할 때도 같은 이름으로 서버에 보낸다.
 * dataMap 의 키(file_01_1)와 글자 하나까지 같아야 한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 키 규칙을 바꾸면 dataMap 의 키 이름도 함께 바꾼다
 * @param
 * @returns
 * @hidden N
*/
scwin.getAttachFieldKey = function (key) {
	return "file_" + key.fileTpCd + "_" + key.fileSeq;
};

/**
 * @method
 * @name scwin.clearAttachSlot
 * @author Inswave
 * @date 2026. 08. 18
 * @description 정의된 슬롯을 모두 비운다.
 *
 * 조회 결과를 표시하기 전에 먼저 비운다.
 * 비우지 않으면 다시 조회했을 때 이전 파일명이 남는다.
 *
 * ATTACH_SLOT 을 훑기 때문에 슬롯을 늘려도 이 함수는 고치지 않는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.clearAttachSlot = function () {
	scwin.forEachAttachSlot(component => component.setValue(""));
};

/**
 * @method
 * @name scwin.forEachAttachSlot
 * @author Inswave
 * @date 2026. 08. 18
 * @description 정의된 슬롯을 하나씩 돌며 넘겨받은 일을 시킨다.
 *
 * 슬롯을 훑는 코드가 여러 곳에 흩어지지 않도록 한 곳에 모았다.
 * 마크업에 없는 슬롯은 건너뛴다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 없음. ATTACH_SLOT 만 고치면 된다
 * @param
 * @returns
 * @hidden N
*/
scwin.forEachAttachSlot = function (callback) {
	scwin.ATTACH_SLOT.forEach(slot => {
		for (let seq = 1; seq <= slot.count; seq++) {
			const key = { fileTpCd : slot.fileTpCd, fileSeq : String(seq) };
			const component = scwin.getAttachComponent(key);

			// 표에는 있는데 마크업에 없는 슬롯은 건너뛴다.
			if (component === null) continue;

			callback(component, key, slot);
		}
	});
};

/**
 * @method
 * @name scwin.setAttachFileName
 * @author Inswave
 * @date 2026. 08. 18
 * @description 조회된 첨부 목록의 파일명을 슬롯별 입력칸에 표시한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.setAttachFileName = function () {
	// 이전 조회 결과가 남지 않도록 먼저 비운다.
	scwin.clearAttachSlot();

	const rowCount = dlt_attach.getRowCount();

	for (let i = 0; i < rowCount; i++) {
		const key = {
			fileTpCd : dlt_attach.getCellData(i, "fileTpCd"),
			fileSeq : dlt_attach.getCellData(i, "fileSeq")
		};

		const component = scwin.getAttachComponent(key);

		// 조회된 구분코드에 해당하는 슬롯이 화면에 없을 수 있다.
		if (component === null) continue;

		component.setValue(dlt_attach.getCellData(i, "fileNm"));
	}
};

/**
 * @method
 * @name scwin.validateAttach
 * @author Inswave
 * @date 2026. 08. 18
 * @description 필수 첨부가 들어 있는지 확인한다.
 *
 * 슬롯 id 를 직접 적지 않고 구분코드로 찾는다.
 * 마크업에서 슬롯 위치가 바뀌어도 이 함수는 그대로 둔다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 필수 첨부 구분코드 목록
 * @param
 * @returns
 * @hidden N
*/
scwin.validateAttach = async function () {
	// 저장 전 반드시 있어야 하는 첨부의 구분코드. 01 신청서
	for (const fileTpCd of ["01"]) {
		const slot = scwin.ATTACH_SLOT.find(item => item.fileTpCd === fileTpCd);

		if (slot === undefined) continue;

		if (scwin.hasAttachFile(fileTpCd)) continue;

		await $c.win.alert($c.data.getMessage("com_crud_0199", slot.name));
		return false;
	}

	return true;
};

/**
 * @method
 * @name scwin.hasAttachFile
 * @author Inswave
 * @date 2026. 08. 18
 * @description 해당 구분의 슬롯 중 하나라도 파일이 들어 있는지 본다.
 * @param
 * @returns
 * @hidden N
*/
scwin.hasAttachFile = function (fileTpCd) {
	let hasFile = false;

	scwin.forEachAttachSlot((component, key) => {
		if (key.fileTpCd !== fileTpCd) return;
		if ($c.util.isNotEmpty(component.getValue())) hasFile = true;
	});

	return hasFile;
};

/**
 * @method
 * @name scwin.removeAttachFile
 * @author Inswave
 * @date 2026. 08. 18
 * @description 슬롯을 비우고, 이미 저장된 파일이면 삭제 대상 목록에 담는다.
 *
 * 화면에서 지우는 것만으로는 서버 파일이 지워지지 않는다.
 * 저장할 때 함께 보내야 서버가 지운다.
 * @param
 * @returns
 * @hidden N
*/
scwin.removeAttachFile = function (key) {
	const component = scwin.getAttachComponent(key);

	if (component === null) return;

	if ($c.util.isEmpty(component.getValue())) return;

	// 조회된 목록에 있으면 이미 서버에 저장된 파일이다.
	const rowCount = dlt_attach.getRowCount();

	for (let i = 0; i < rowCount; i++) {
		if (dlt_attach.getCellData(i, "fileTpCd") !== key.fileTpCd) continue;
		if (dlt_attach.getCellData(i, "fileSeq") !== key.fileSeq) continue;

		scwin.delAttachList.push(key);
		break;
	}

	// UDC 가 보관 중인 파일을 버리고 dataMap 의 파일명도 비운다.
	// 입력칸만 비우면 파일은 UDC 안에 남아 저장할 때 딸려 간다.
	mud.detachFileFromMap(scwin.getAttachFieldKey(key), dma_detail);
};

/**
 * @method
 * @name scwin.downloadAttachFile
 * @author Inswave
 * @date 2026. 08. 18
 * @description 이미 저장된 첨부파일을 내려받는다.
 *
 * 방금 고른 파일은 아직 서버에 없어 내려받을 수 없다.
 *
 * $c.data.downFile 은 async 라 실패 시 reject 한다.
 * catch 를 붙이지 않으면 서버가 죽어 있어도 화면에 아무 반응이 없다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 내려받기 경로, 파라미터
 * @param
 * @returns
 * @hidden N
*/
scwin.downloadAttachFile = async function (key) {
	const rowCount = dlt_attach.getRowCount();

	for (let i = 0; i < rowCount; i++) {
		if (dlt_attach.getCellData(i, "fileTpCd") !== key.fileTpCd) continue;
		if (dlt_attach.getCellData(i, "fileSeq") !== key.fileSeq) continue;

		const fileName = dlt_attach.getCellData(i, "fileNm");

		await $c.data.downFile("/api/listing/listinvstg/specialized-evaluation/file-download", fileName, {
			aplcNo : scwin.aplcNo,
			fileTpCd : key.fileTpCd,
			fileSeq : key.fileSeq
		}).catch(() => { $c.win.alert("파일을 내려받지 못했습니다."); });
		return;
	}
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 08. 18
 * @description 저장 전 입력값을 검증한다.
 *
 * 두 단계로 나눈다.
 * 1. 필수·자리수는 공통함수 $c.data.validateGroup 에 맡긴다. 직접 for 문을 돌지 않는다.
 * 2. 형식 검증은 항목마다 규칙이 달라 공통함수를 하나씩 부른다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - valInfo 항목, 형식 검증 대상
 * @param
 * @returns
 * @hidden N
*/
scwin.validate = async function () {
	const valInfo = [
		{ id : "comNm", mandatory : true },
		{ id : "repNm", mandatory : true },
		{ id : "bzRegNo1", mandatory : true },
		{ id : "bzRegNo2", mandatory : true },
		{ id : "bzRegNo3", mandatory : true },
		{ id : "foundDd", mandatory : true },
		{ id : "zipCd", mandatory : true },
		{ id : "apctNm", mandatory : true },
		{ id : "apctEmail", mandatory : true },
		{ id : "coreValuObjNm", mandatory : true },
		{ id : "apctDd", mandatory : true }
	];

	if (!await $c.data.validateGroup(grp_form, valInfo)) return false;

	if (!await scwin.validateFormat()) return false;

	return await scwin.validateAttach();
};

/**
 * @method
 * @name scwin.validateFormat
 * @author Inswave
 * @date 2026. 08. 18
 * @description 업무 형식 검증. 사업자등록번호·이메일·전화번호를 공통함수로 본다.
 *
 * 정규식을 화면에서 새로 쓰지 않는다. 화면마다 규칙이 달라지면 데이터가 섞인다.
 *
 * isBizID 는 체크섬만 본다. 자리수 검사가 없어 10자리가 아니면 엉뚱한 결과가 나오므로
 * 길이를 먼저 확인한 뒤 부른다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 검증 대상 항목
 * @param
 * @returns
 * @hidden N
*/
scwin.validateFormat = async function () {
	// 사업자등록번호 : 3-2-5 세 칸을 합쳐 10자리로 본다.
	const bizNo = scwin.getBizRegNo();

	if (bizNo.length !== 10 || !$c.str.isBizID(bizNo)) {
		await $c.win.alert("사업자등록번호가 올바르지 않습니다.");
		ipt_bzRegNo1.focus();
		return false;
	}

	// 이메일
	if (!$c.str.isEmail(dma_detail.get("apctEmail"))) {
		await $c.win.alert($c.data.getMessage("com_valid_format_0037"));
		ipt_apctEmail.focus();
		return false;
	}

	// 전화번호 : 세 칸을 합쳐 본다. 비어 있으면 넘어간다.
	const telNo = scwin.getTelNo();

	if ($c.util.isNotEmpty(telNo) && !$c.str.isPhone(telNo)) {
		await $c.win.alert("연락처 형식이 올바르지 않습니다.");
		ipt_telNo1.focus();
		return false;
	}

	return true;
};

/**
 * @method
 * @name scwin.getBizRegNo
 * @author Inswave
 * @date 2026. 08. 18
 * @description 세 칸에 나뉜 사업자등록번호를 하나로 합친다.
 *
 * 화면은 칸을 나눠 받고 서버에는 붙여서 보낸다.
 * 합치는 규칙을 한 곳에만 두어야 검증과 저장이 어긋나지 않는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.getBizRegNo = function () {
	return (dma_detail.get("bzRegNo1") ?? "")
		+ (dma_detail.get("bzRegNo2") ?? "")
		+ (dma_detail.get("bzRegNo3") ?? "");
};

/**
 * @method
 * @name scwin.getTelNo
 * @author Inswave
 * @date 2026. 08. 18
 * @description 세 칸에 나뉜 전화번호를 하이픈으로 잇는다.
 *
 * isPhone 은 하이픈이 들어간 형태를 정상으로 본다.
 * @param
 * @returns
 * @hidden N
*/
scwin.getTelNo = function () {
	const parts = [dma_detail.get("telNo1"), dma_detail.get("telNo2"), dma_detail.get("telNo3")];

	if (parts.some(part => $c.util.isEmpty(part))) return "";

	return parts.join("-");
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 08. 18
 * @description 검증하고 저장한다. 입력값과 첨부파일을 한 번에 보낸다.
 *
 * 전송은 공통 UDC 의 saveMapForm 이 맡는다.
 * dataMap 을 넘기면 값은 json 파트로, UDC 가 보관 중인 파일은 파일 파트로
 * 하나의 요청에 실어 보낸다. FormData 를 직접 만들 필요가 없다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - saveUrl, onSuccess 에서 할 일
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
	if (!await scwin.validate()) return;

	if (!await $c.win.confirm($c.data.getMessage("com_crud_0198", "저장"))) return;

	// 화면이 나눠 받은 값을 서버가 받는 모양으로 합쳐 넣는다.
	dma_detail.set("bzRegNo", scwin.getBizRegNo());
	dma_detail.set("telNo", scwin.getTelNo());

	// 반복 입력한 값과 삭제 표시도 dataMap 에 넣는다.
	// saveMapForm 은 dataMap 하나만 보내므로 전문에 담을 것은 모두 여기에 모은다.
	dma_detail.set("agnccomMbrNoList", scwin.getRepeatValues(gen_leadCom, "sel_leadCom", "leadComCd"));
	dma_detail.set("specyValuInstCdList", scwin.getRepeatValues(gen_excInst, "sel_excInst", "excInstCd"));
	dma_detail.set("delAttachFileNo", scwin.delAttachList);

	// 신규 등록과 수정은 서버 경로가 다르다. 신청번호가 있으면 이미 저장된 건이다.
	await mud.saveMapForm({
		dataMap : dma_detail,
		saveUrl : scwin.aplcNo
			? "/api/listing/listinvstg/specialized-evaluation/modify"
			: "/api/listing/listinvstg/specialized-evaluation/register",
		onSuccess : async function (res) {
			await $c.win.alert($c.data.getMessage("com_complete_0150", "저장"));
			$c.win.moveUrl("/ui/sample/template/ULDFIL59400.xml", {});
		},
		onError : function (error) {
			$c.win.alert($c.data.getMessage("com_complete_0151", "저장"));
		}
	});
};
